def prime(p):
    if p == 1:
        return False
    fl=True
    for i in range(2,math.ceil(p**0.5) + 1):
        if p % i == 0:
            fl=False
    return fl

def sum_of_primes(k):
    fl=True
    for i in range((k // 2) + 1):
        if prime(i) and prime(k-i):
            fl=True
            break
    return fl

if prime(n):
